def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    if not isinstance(l, list):
        raise TypeError("Input must be a list")
    if not l:
        return []

    # Count occurrences of each element
    count = {}
    for elem in l:
        if elem in count:
            count[elem] += 1
        else:
            count[elem] = 1

    # Sort elements based on their count and then their value
    sorted_l = sorted(count.items(), key=lambda x: (x[1], x[0]))

    # Return unique elements in sorted order
    return [elem for elem, _ in sorted_l]

