def cyclic_transform(s: str, direction: str) -> str:
    """
    returns encoded or decoded string by cycling groups of three characters.
    """
    if not s:  # Check for empty string
        return ""

    groups = [s[(3 * i):min((3 * i + 3), len(s))] for i in range((len(s) + 2) // 3)]
    groups = [(group[1:] + group[0]) if len(group) == 3 else group for group in groups]

    if direction == 'encode':
        return "".join(groups)
    elif direction == 'decode':
        decoded_string = ""
        for i in range(len(groups)):
            decoded_string += groups[i] + (groups[(i - 1) % len(groups)] if i > 0 else "")
        return decoded_string
    else:
        raise ValueError("Invalid direction. Please use 'encode' or 'decode'.")

